private String readUtf(int constantPoolEntryIndex, char[] charBuffer) {
    IntStream.Range(constantPoolEntryIndex, constantPoolEntryIndex + 3).
            ForEach(index -> {
                if (classFileBuffer.get(index) == (byte) 0) {
                    throw new RuntimeException("Invalid UTF entry");
                }
            });

    int stringLength = classFileBuffer.get(constantPoolEntryIndex + 1);
    IntStream.Range(constantPoolEntryIndex + 2, constantPoolEntryIndex + 2 + stringLength).
            ForEach(index -> {
                charBuffer[index - (constantPoolEntryIndex + 2)] = (char) classFileBuffer.get(index);
            });

    return new String(charBuffer, 0, stringLength);
}

