private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Find the first node that satisfies the predicate, starting from the start node
    Node current = start;
    while (predicate.test(current) != true && current != stop) {
        current = current.getNeighbor(dir);
    }

    // If the current node satisfies the predicate, return a circulator to it
    if (predicate.test(current) == true) {
        return new OuterFaceCirculator(current, dir);
    }

    // Otherwise, find the first node that does not satisfy the predicate, starting from the start node
    while (predicate.test(current) == false && current != stop) {
        current = current.getNeighbor(dir);
    }

    // If the current node does not satisfy the predicate, return a circulator to it
    if (predicate.test(current) == false) {
        return new OuterFaceCirculator(current, dir);
    }

    // Otherwise, return a circulator to the stop node
    return new OuterFaceCirculator(stop, dir);
}

