public static void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Moves all vertices from the bucket with label minLabel to the bucket with label 0
    for (Integer vertex : bucketsByLabel.get(minLabel)) {
        bucketsByLabel.get(0).add(vertex);
    }

    // Clears the bucket with label minLabel
    bucketsByLabel.get(minLabel).clear();

    // Updates the labeling accordingly
    for (Integer vertex : labels) {
        if (bucketsByLabel.get(0).contains(vertex)) {
            labels.set(labels.indexOf(vertex), 0);
        }
    }
}

