public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder builder = new StringBuilder(str.length());
    int pos = 0;
    while (pos < str.length()) {
        char c = str.charAt(pos);
        if (c == '\\') {
            pos++;
            if (pos < str.length()) {
                c = str.charAt(pos);
                switch (c) {
                    case 'b':
                        builder.append('\b');
                        break;
                    case 't':
                        builder.append('\t');
                        break;
                    case 'n':
                        builder.append('\n');
                        break;
                    case 'f':
                        builder.append('\f');
                        break;
                    case 'r':
                        builder.append('\r');
                        break;
                    case '\\':
                    case '\'':
                    case '\"':
                    case '/':
                        builder.append(c);
                }
                pos++;
            }
        } else {
            builder.append(c);
            pos++;
        }
    }
    return builder.toString();
}

