public static int computeUTF8Size(String str, int index, int len) {
    int size = 0;
    for (int i = index; i < len; i++) {
        char c = str.charAt(i);
        if (c >= 0 && c <= 0x7F) {
            size++;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c)) {
            i++;
            if (Character.isLowSurrogate(str.charAt(i))) {
                size += 4;
            } else {
                throw new IllegalArgumentException("Invalid low surrogate");
            }
        } else {
            size += 3;
        }
    }
    return size;
}

